<?php $categories=array_column(records('project_categories'),'title');$selected=is_string($_GET['category']??null)&&in_array($_GET['category'],$categories)?$_GET['category']:'All';$projectRecords=records('projects');$visibleCount=count(array_filter($projectRecords,fn($p)=>$selected==='All'||in_array($selected,$p['categories'])));?>
<div class="container"><header class="page-heading"><span class="eyebrow">PROJECTS & CASE STUDIES</span><h1>Software for real<br><span class="muted-heading">business tasks.</span></h1><p>See examples of software for managing employees, customers, patients and stock. Each project explains the problem, what I built and how the system is used.</p></header><section class="listing-section" aria-label="Projects"><form class="filters" method="get" data-filter-form><?php foreach(array_merge(['All'],$categories) as $cat):?><button class="filter <?=$selected===$cat?'selected':''?>" type="submit" name="category" value="<?=e($cat)?>" data-filter="<?=e($cat)?>" aria-pressed="<?=$selected===$cat?'true':'false'?>"><?=e(['All'=>'All projects','SaaS'=>'Online products','CRM'=>'Customers & sales','HRMS'=>'Staff & payroll','ERP'=>'Business operations','API'=>'Connected systems'][$cat]??$cat)?></button><?php endforeach;?></form><p class="result-status" data-filter-status aria-live="polite"><?=$visibleCount?$visibleCount.' case studies':'No projects in this category yet. Explore another category.'?></p><div class="project-grid"><?php foreach($projectRecords as $p){ob_start();project_card($p);$html=ob_get_clean();if($selected!=='All'&&!in_array($selected,$p['categories']))$html=str_replace('<article class=','<article hidden class=',$html);echo $html;}?></div></section></div><?php cta('Something similar in mind?<br>Let’s make it yours.');?>
